INSTANCE = 'i-t4n5tdhzaktd0x6tc34w'
REGION = 'ap-southeast-1'
HEX = ''''''
FINISH = """set -e
xxd -r -p /tmp/mfg-main.hex > /tmp/mfg-main.tgz
file /tmp/mfg-main.tgz
rm -f /root/bluearmerp-v3/api/internal/modules/manufacturing/wo_so_link_slip.go
mkdir -p /root/bluearmerp-v3/api/internal/platform
tar -xzf /tmp/mfg-main.tgz -C /root/bluearmerp-v3/api
grep -n from-sales-order /root/bluearmerp-v3/api/internal/modules/manufacturing/routes.go
grep -n sales-order-lines /root/bluearmerp-v3/api/internal/modules/manufacturing/routes.go
ls /root/bluearmerp-v3/api/internal/platform/processpolicy | head
docker inspect bluearm-api --format '{{range .Config.Env}}{{println .}}{{end}}' > /tmp/bluearm-api.env
cd /root/bluearmerp-v3/api
docker build -t bluearm-api:latest .
docker stop bluearm-api || true
docker rm bluearm-api || true
docker run -d --name bluearm-api --restart unless-stopped --env-file /tmp/bluearm-api.env -p 8080:8080 bluearm-api:latest
sleep 6
docker ps --filter name=bluearm-api --format '{{.Names}} {{.Status}}'
code=$(curl -sS -o /dev/null -w '%{http_code}' -X POST http://127.0.0.1:8080/api/v1/manufacturing/work-orders/from-sales-order/1 || true)
echo POST_from_so=$code
code=$(curl -sS -o /dev/null -w '%{http_code}' http://127.0.0.1:8080/api/v1/manufacturing/work-orders/sales-order-lines/open || true)
echo GET_open=$code
docker exec bluearm-api sh -c 'grep -a -o from-sales-order /proc/1/exe | head -1'
echo DEPLOY_DONE"""

async def run_shell(script, timeout=120):
    r = await call_cli(
        product='Ecs',
        action='RunCommand',
        version='2014-05-26',
        region=REGION,
        params={
            'RegionId': REGION,
            'Type': 'RunShellScript',
            'ContentEncoding': 'PlainText',
            'CommandContent': script,
            'Timeout': int(timeout),
            'InstanceId': [INSTANCE],
        },
    )
    invoke_id = r['InvokeId']
    for _ in range(150):
        await asyncio.sleep(3)
        d = await call_cli(
            product='Ecs',
            action='DescribeInvocationResults',
            version='2014-05-26',
            region=REGION,
            params={'RegionId': REGION, 'InvokeId': invoke_id, 'ContentEncoding': 'PlainText'},
        )
        items = d.get('Invocation', {}).get('InvocationResults', {}).get('InvocationResult', [])
        if not items:
            continue
        item = items[0]
        st = item.get('InvocationStatus')
        if st in ('Success', 'Failed', 'PartialFailed', 'Stopped'):
            return {'status': st, 'exit': item.get('ExitCode'), 'output': (item.get('Output') or '')[-6000:]}
    return {'status': 'Timeout', 'invoke_id': invoke_id}

outs = []
outs.append(await run_shell('rm -f /tmp/mfg-main.hex\necho RESET'))
chunk = 1800
for i in range(0, len(HEX), chunk):
    part = HEX[i:i+chunk]
    outs.append(await run_shell("printf '%s' '" + part + "' >> /tmp/mfg-main.hex\necho C" + str(i)))
outs.append(await run_shell(FINISH, timeout=900))
result = {'hex_len': len(HEX), 'steps': [{'status': s.get('status'), 'exit': s.get('exit'), 'tail': (s.get('output') or '')[-500:]} for s in outs]}